CREATE OR REPLACE FUNCTION fn_preparar_importacion_revision(p_importacion_id UUID, p_proveedor TEXT) RETURNS void AS $$ DECLARE v_totales INT := 0; BEGIN SELECT COUNT(*) INTO v_totales FROM listas_precios_raw_staging WHERE importacion_id = p_importacion_id; INSERT INTO listas_precios_raw (importacion_id, proveedor, fila_num, payload, columnas_guardadas) SELECT importacion_id, proveedor, fila_num, payload, columnas_guardadas FROM listas_precios_raw_staging WHERE importacion_id = p_importacion_id; DELETE FROM listas_precios_raw_staging WHERE importacion_id = p_importacion_id; UPDATE importaciones_excel SET resumen_diff = jsonb_build_object('totales', v_totales, 'nuevos', v_totales, 'modificados', 0, 'eliminados', 0) WHERE id = p_importacion_id; SET LOCAL session_replication_role = 'replica'; UPDATE listas_precios_proveedor SET vigente = false WHERE proveedor = p_proveedor AND vigente = true; INSERT INTO listas_precios_proveedor (proveedor, importacion_id, vigente, total_filas) VALUES (p_proveedor, p_importacion_id, true, v_totales); SET LOCAL session_replication_role = 'origin'; UPDATE importaciones_excel SET estado = 'completado'::estado_importacion_excel, ultima_actividad = now() WHERE id = p_importacion_id; INSERT INTO importacion_eventos (importacion_id, estado_paso, mensaje) VALUES (p_importacion_id, 'CONSOLIDADO', 'Lista de precios actualizada (Diff omitido por rendimiento).'); END; $$ LANGUAGE plpgsql SECURITY DEFINER; DO $$ DECLARE r RECORD; BEGIN FOR r IN SELECT id, proveedor FROM importaciones_excel WHERE estado = 'mapeando' AND filas_procesadas = total_filas AND filas_procesadas > 0 LOOP PERFORM fn_preparar_importacion_revision(r.id, r.proveedor); END LOOP; END; $$ ;